<?php
function ald_page_start($admin=false) { ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alumni document services | AYISEC</title><link rel="stylesheet" href="css/alumni-documents.css?v=20261012"><link rel="stylesheet" href="css/alumni-admin-theme.css?v=1"></head><body class="<?php echo $admin?'ald-admin':'ald-member'; ?>"><main>
<nav><a href="<?php echo $admin?'alumni-hub.php':'alumni-community.php'; ?>">&larr; <?php echo $admin?'Alumni management':'Alumni community'; ?></a><a href="<?php echo $admin?'dashboard.php':'alumni-profile.php'; ?>"><?php echo $admin?'Home':'My profile'; ?></a></nav>
<header><span class="eyebrow">AYISEC · Old students</span><h1><?php echo $admin?'Document service desk':'Your school documents, requested online'; ?></h1><p><?php echo $admin?'Configure services, review requests and manage delivery. Payment confirmation comes directly from the payment gateway.':'Request a certificate held by the school, a testimonial, transcript or another available document. Staff review availability before you pay.'; ?></p><div class="steps"><span>1 · Submit request</span><span>2 · School review</span><span>3 · Secure payment</span><span>4 · Collection or delivery</span></div></header>
<?php if (!empty($_SESSION['ald_flash'])) { ?><div class="notice" role="status"><?php echo alumni_safe($_SESSION['ald_flash']); unset($_SESSION['ald_flash']); ?></div><?php } }
function ald_csrf() { echo '<input type="hidden" name="csrf" value="'.alumni_safe(alumni_csrf_token()).'">'; }
function ald_label($value) { return ucwords(str_replace('_',' ',$value)); }
function ald_request_detail($con,$r,$admin=false) {
    $details=json_decode($r['details'],true) ?: array(); ?>
<section class="card" id="request-detail"><h2>Request #<?php echo (int)$r['id']; ?> · <?php echo alumni_safe($r['servicename']); ?></h2>
<?php if($r['paymentmode']==='test') { ?><div class="notice error">Test payment only — no real funds received. Documents must not be released against this request.</div><?php } ?>
<p><span class="badge"><?php echo alumni_safe(ald_label($r['status'])); ?></span> <span class="badge">Payment: <?php echo alumni_safe(ald_label($r['paymentstatus'])); ?></span></p>
<dl><dt>Submitted</dt><dd><?php echo alumni_safe($r['createdat']); ?></dd><dt>Service fee</dt><dd><?php echo ald_price($r['fee']); ?></dd><dt>Delivery fee</dt><dd><?php echo ald_price($r['deliveryfee']); ?></dd><dt>Total</dt><dd><?php echo ald_price($r['total']); ?></dd><dt>Delivery method</dt><dd><?php echo alumni_safe(ald_label($r['delivery'])); ?></dd><dt>Receipt email</dt><dd><?php echo alumni_safe($r['receiptemail']); ?></dd>
<?php foreach($details as $key=>$value) { if($value==='')continue; ?><dt><?php echo alumni_safe(ald_label($key)); ?></dt><dd><?php echo alumni_safe($value); ?></dd><?php } ?>
<dt>Payment reference</dt><dd><?php echo alumni_safe($r['reference']); ?></dd><?php if($r['paidat']) { ?><dt>Paid at</dt><dd><?php echo alumni_safe($r['paidat']); ?></dd><?php } ?>
<?php if($r['staffnote']) { ?><dt>School update</dt><dd><?php echo alumni_safe($r['staffnote']); ?></dd><?php } ?></dl>
<?php if($r['status']==='awaiting_payment') { ?><form method="post"><?php ald_csrf(); ?><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><div class="actions"><?php if(!$admin) { ?><button name="action" value="pay">Pay <?php echo ald_price($r['total']); ?></button><?php } ?><button class="secondary" name="action" value="verify">Check payment</button></div><p class="muted">Already debited? Check payment before trying again. Never pay a new request for the same document while this payment is unresolved.</p></form><?php } ?>
<?php if($admin) { ?><form method="post"><?php ald_csrf(); ?><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><div class="fields"><label>Request status<select name="status"><?php foreach(array('submitted','awaiting_payment','processing','needs_attention','ready','dispatched','completed','rejected') as $status) { ?><option value="<?php echo $status; ?>" <?php echo $status===$r['status']?'selected':''; ?>><?php echo $status==='awaiting_payment'?'Approve — allow payment':ald_label($status); ?></option><?php } ?></select></label><label>Update for the alumnus<textarea name="note" maxlength="2000" placeholder="Collection instructions, tracking number or delivery update"><?php echo alumni_safe($r['staffnote'] ?? ''); ?></textarea></label></div><p class="muted">Before approval, confirm document availability, recipient details and the quoted delivery fee. Fulfilment and any refunds are handled by school staff; this page does not send documents or refund payments automatically.</p><button name="action" value="status">Save update</button></form><?php } ?>
<details><summary>Request history</summary><ul class="history"><?php foreach(ald_rows($con,'SELECT event,note,createdat FROM tblalumnidocevent WHERE requestid=? ORDER BY id DESC LIMIT 50',array($r['id'])) as $e) { ?><li><?php echo alumni_safe($e['createdat'].' · '.ald_label($e['event']).($e['note']!==''?' — '.$e['note']:'')); ?></li><?php } ?></ul></details></section>
<?php }
function ald_list($con,$memberid=null,$status='') {
    $params=array(); $where='1=1';
    if($memberid!==null) { $where.=' AND r.alumniid=?'; $params[]=$memberid; }
    if($status!=='') { $where.=' AND r.status=?'; $params[]=$status; }
    $count=(int)ald_rows($con,'SELECT COUNT(*) n FROM tblalumnidocrequest r WHERE '.$where,$params)[0]['n'];
    $pages=max(1,(int)ceil($count/20)); $page=min($pages,max(1,(int)($_GET['page']??1))); $offset=($page-1)*20;
    $rows=ald_rows($con,'SELECT r.*,a.fullname FROM tblalumnidocrequest r LEFT JOIN tblalumni a ON a.alumniid=r.alumniid WHERE '.$where.' ORDER BY r.id DESC LIMIT 20 OFFSET '.$offset,$params); ?>
<section class="card"><h2><?php echo $memberid===null?'All requests':'My requests'; ?> <span class="badge"><?php echo $count; ?></span></h2><?php if(!$rows) { ?><p class="muted">No requests to show yet.</p><?php } else { ?><div class="table-wrap"><table><thead><tr><th>Request</th><?php if($memberid===null) { ?><th>Alumnus</th><?php } ?><th>Document</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($rows as $r) { ?><tr><td><a href="?<?php echo http_build_query(array('id'=>$r['id'],'page'=>$page,'status'=>$status)); ?>#request-detail">#<?php echo (int)$r['id']; ?></a></td><?php if($memberid===null) { ?><td><?php echo alumni_safe($r['fullname']??'Alumnus'); ?></td><?php } ?><td><?php echo alumni_safe($r['servicename']); ?></td><td><?php echo ald_price($r['total']); ?></td><td><?php echo alumni_safe(ald_label($r['status'])); ?></td><td><?php echo alumni_safe(ald_label($r['paymentstatus']).($r['paymentmode']==='test'?' (TEST ONLY)':'')); ?></td></tr><?php } ?></tbody></table></div><?php } ?>
<div class="pagination"><?php if($page>1) { ?><a href="?<?php echo http_build_query(array('page'=>$page-1,'status'=>$status)); ?>">&larr; Previous</a><?php } ?><span>Page <?php echo $page.' of '.$pages; ?></span><?php if($page<$pages) { ?><a href="?<?php echo http_build_query(array('page'=>$page+1,'status'=>$status)); ?>">Next &rarr;</a><?php } ?></div></section>
<?php }
